// loader.c - loads ringbuf.bpf.o, attaches it, and prints execve events
#include <stdio.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <linux/types.h>
#include <bpf/libbpf.h>
#include "common.h"        // shared exec_event struct
#include "ringbuf.skel.h"  // generated by bpftool

// A signal handler may only set a flag: nothing else is async-signal-safe.
static volatile sig_atomic_t stop = 0;
static void on_signal(int sig) { (void)sig; stop = 1; }

// Called once per event pulled from the ring buffer.
static int handle_event(void *ctx, void *data, size_t size)
{
    const struct exec_event *e = data;
    if (size < sizeof(*e))
        return 0;   // ignore malformed events
    printf("%-8u %-8u %-6u %-12llu %-16s %s\n", e->pid, e->ppid, e->uid, (unsigned long long)e->cgroup_id, e->comm, e->filename);
    return 0;
}

int main(void)
{
    struct ringbuf_bpf *skel = NULL;
    struct ring_buffer *rb = NULL;
    struct sigaction sa;
    int err = 0;

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // 1) open + load: parse the embedded object and run the verifier
    skel = ringbuf_bpf__open_and_load();
    if (!skel) {
        fprintf(stderr, "failed to open/load BPF skeleton\n");
        return 1;
    }

    // 2) attach: hooks the program to the sys_enter_execve tracepoint
    err = ringbuf_bpf__attach(skel);
    if (err) {
        fprintf(stderr, "failed to attach: %d\n", err);
        goto cleanup;
    }

    // 3) connect the ring buffer map to our callback
    rb = ring_buffer__new(bpf_map__fd(skel->maps.events), handle_event, NULL, NULL);
    if (!rb) {
        fprintf(stderr, "failed to create ring buffer\n");
        err = 1;
        goto cleanup;
    }

    printf("%-8s %-8s %-6s %-12s %-16s %s\n", "PID", "PPID", "UID", "CGROUP_ID", "COMM", "FILENAME");

    // 4) poll loop: sleeps in epoll until data arrives (or 100 ms passes)
    while (!stop) {
        err = ring_buffer__poll(rb, 100);
        if (err == -EINTR) {        // Ctrl+C interrupted the wait
            err = 0;
            break;
        }
        if (err < 0) {
            fprintf(stderr, "poll error: %d\n", err);
            break;
        }
    }

cleanup:
    ring_buffer__free(rb);          // safe to call with NULL
    ringbuf_bpf__destroy(skel);     // detaches and frees everything
    return err < 0 ? 1 : err;
}
